// Version floor for the fixed Claude profiles generated by RuntimeGateway.
export const PROFILE_MINIMUM_VERSIONS = Object.freeze({
  'read-only': '2.1.248',
  'read-only-streaming': '2.1.259',
});

export function isVersionAtLeast(version, minimum) {
  const parse = (value) => typeof value === 'string' && /^(\d+)\.(\d+)\.(\d+)$/.test(value)
    ? value.split('.').map(Number) : null;
  const actual = parse(version);
  const required = parse(minimum);
  if (!actual || !required || [...actual, ...required].some((part) => !Number.isSafeInteger(part))) return false;
  for (let index = 0; index < 3; index++) {
    if (actual[index] !== required[index]) return actual[index] > required[index];
  }
  return true;
}
